/usr/bin/zsh -lc "python3 - <<'PY'
from pathlib import Path
rows=[]
for line in Path('problem.txt').read_text().splitlines():
    parts=line.split()
    if len(parts)==6 and parts[0].endswith('ns') and parts[0][:-2].isdigit():
        rows.append(parts)
tb='''"'`timescale 1ns/1ps
module dev_tb;
    logic clk = 0;
    logic a = 1;
    logic b = 1'"'bx;
    wire q, state;
    integer checks = 0;
    integer s, pair;
    logic expected_q, expected_state;
    TopModule dut (.clk(clk), .a(a), .b(b), .q(q), .state(state));

    task automatic check(input logic es, input logic eq);
        begin
            if (state "'!== es || q !== eq)
                $fatal(1, "Mismatch at %0t: state=%b expected=%b q=%b expected=%b", $time, state, es, q, eq);
            checks = checks + 1;
        end
    endtask

    // Explicit truth table independently records the eight observed combinations.
    function automatic logic truth_q(input logic st, aa, bb);
        case ({st,aa,bb})
            3'"'b000: truth_q = 0;
            3'b001: truth_q = 1;
            3'b010: truth_q = 1;
            3'b011: truth_q = 0;
            3'b100: truth_q = 1;
            3'b101: truth_q = 0;
            3'b110: truth_q = 0;
            3'b111: truth_q = 1;
            default: truth_q = 1'bx;
        endcase
    endfunction

    initial begin
'''
for i,(t,c,a,b,s,q) in enumerate(rows):
    if i: tb+='        #4.999;\\n'
    tb+=f\"        clk = 1'b{c};\\n        #0.001;\\n        a = 1'b{a}; b = 1'b{b};\\n        #0; check(1'b{s}, 1'b{q}); // Original row {t}\\n\"
tb+='''
        // Establish each state using external inputs, then exercise every input pair.
        for (s = 0; s < 2; s = s + 1) begin
            for (pair = 0; pair < 4; pair = pair + 1) begin
                clk = 0; a = s[0]; b = s[0];
                #1; clk = 1; #1;
                a = pair[1]; b = pair[0];
                #1; check(s[0], truth_q(s[0], a, b));
                clk = 0; #1;
                check(s[0], truth_q(s[0], a, b));
                // AND's Boolean truth table is one only for input pair 11.
                expected_state = (pair == 3);
                expected_q = truth_q(expected_state, a, b);
                clk = 1; #1; check(expected_state, expected_q);
                clk = 0; #1; check(expected_state, expected_q);
            end
        end
        "'$display("PASS: %0d checks (original waveform, exhaustive truth table, edge sampling and hold)", checks);
        $finish;
    end
    initial begin
        #1000; $fatal(1, "Testbench timeout");
    end
endmodule
'"'''
Path('dev_tb.sv').write_text(tb)
PY
timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/iverilog -g2012 -Wall -s dev_tb -o dev_sim candidate.sv dev_tb.sv > compile.log 2>&1
compile_status="'$?
cat compile.log
printf '"'Compile exit: %s\\n' \""'$compile_status"
if [ "$compile_status" -eq 0 ]; then
    timeout 30s /home/shmin/nl2hdl/.conda_pkgs/iverilog-12.0-ha738cfc_1/bin/vvp dev_sim > simulation.log 2>&1
    sim_status=$?
    cat simulation.log
    printf '"'Simulation exit: %s\\n' \""'$sim_status"
fi'

